  "----#include root\\lizardboard\r\nmice = 0\r\nbunnies = 0\r\nfoxes = 0\r\nwait_id = 0\r\n\r\nfunction onLoad(save_state)\r\n createButtons()\r\n wait_id = Wait.time(updateButtons, 1, -1)\r\nend\r\n\r\nfunction onDestroy()\r\n Wait.stop(wait_id)\r\nend\r\n\r\nfunction nothing()\r\nend\r\n\r\nfunction addCard(suit)\r\n suit = suit:lower()\r\n if string.contains(suit,\"fox\") then\r\n foxes = foxes + 1\r\n end\r\n if string.contains(suit,\"mouse\") then\r\n mice = mice + 1\r\n end\r\n if string.contains(suit,\"rabbit\") then\r\n bunnies= bunnies + 1\r\n end\r\nend\r\n\r\nfunction createButtons()\r\n self.createButton({\r\n click_function = \"nothing\",\r\n function_owner = self,\r\n label = '0',\r\n position = {0.7, 0.1, -0.17},\r\n scale = {0.5, 0.5, 0.5},\r\n width = 0,\r\n height = 0,\r\n font_size = 120\r\n })\r\n self.createButton({\r\n click_function = \"nothing\",\r\n function_owner = self,\r\n label = '0',\r\n position = {0.9, 0.1, -0.17},\r\n scale = {0.5, 0.5, 0.5},\r\n width = 0,\r\n height = 0,\r\n font_size = 120\r\n })\r\n self.createButton({\r\n click_function = \"nothing\",\r\n function_owner = self,\r\n label = '0',\r\n position = {1.09, 0.1, -0.17},\r\n scale = {0.5, 0.5, 0.5},\r\n width = 0,\r\n height = 0,\r\n font_size = 120\r\n })\r\nend\r\n\r\nfunction updateButtons()\r\n mice = 0\r\n foxes = 0\r\n bunnies = 0\r\n items = Physics.cast({\r\n origin = self.positionToWorld({-0.90, 0.2, 0.55}),\r\n direction = self.getTransformUp(),\r\n type = 3,\r\n size = {3, 0.1, 6},\r\n max_distance = 2,\r\n })\r\n for _, item in ipairs(items) do\r\n if item.hit_object.tag == \"Card\" then\r\n addCard(item.hit_object.getDescription())\r\n end\r\n if item.hit_object.tag == \"Deck\" then\r\n for _, card in ipairs(item.hit_object.getObjects()) do\r\n addCard(card.description)\r\n end\r\n end\r\n end\r\n\r\n self.editButton({index=0,label=tostring(mice)})\r\n self.editButton({index=1,label=tostring(bunnies)})\r\n self.editButton({index=2,label=tostring(foxes)})\r\nend\r\n\r\n----#include root\\lizardboard","LuaScriptState": "","XmlUI": "","AttachedSnapPoints": [{"Position": {"x": -0.6259084,"y": 0.100000218,"z": -0.632033467},"Rotation": {"x": 5.99166124E-05,"y": 0.0142067941,"z": 4.573914E-05}},{"Position": {"x": -0.769556463,"y": 0.100000188,"z": -0.627778},"Rotation": {"x": 5.99166124E-05,"y": 0.0142067941,"z": 4.573914E-05}},{"Position": {"x": -0.9287303,"y": 0.100000158,"z": -0.6352461},"Rotation": {"x": 5.99166124E-05,"y": 0.0142067941,"z": 4.573914E-05}},{"Position": {"x": -1.08971775,"y": 0.100000158,"z": -0.628967345},"Rotation": {"x": 5.99166124E-05,"y": 0.0142067941,"z": 4.573914E-05}},{"Position": {"x": -0.705245,"y": 0.100001052,"z": -0.0574975833},"Rotation": {"x": -1.8441159E-06,"y": 359.989746,"z": 1.00292164E-06}},{"Position": {"x": -0.891449749,"y": 0.09999992,"z": -0.0575344637},"Rotation": {"x": 7.046069E-07,"y": 359.989777,"z": -2.59421336E-06}},{"Position": {"x": -1.09670246,"y": 0.100001104,"z": -0.0575742759},"Rotation": {"x": 6.749056E-08,"y": 359.989777,"z": 1.34829136E-07}},{"Position": {"x": 0.2950477,"y": 0.09999977,"z": 0.8077995},"Rotation": {"x": 1.1867844E-06,"y": 0.00469916966,"z": 1.89807992E-07}},{"Position": {"x": 0.292307973,"y": 0.0999990553,"z": 0.625745952},"Rotation": {"x": 5.898826E-07,"y": 0.005327547,"z": 1.60074876E-06}},{"Position": {"x": 0.294280678,"y": 0.0999993,"z": 0.444107056},"Rotation": {"x": 9.760769E-07,"y": 359.99295,"z": 7.5864655E-08}},{"Position": {"x": 0.09744962,"y": 0.100001037,"z": 0.624887645},"Rotation": {"x": 3.18591037E-06,"y": 0.00531388726,"z": -1.12621433E-06}},{"Position": {"x": 0.0983459353,"y": 0.100001976,"z": 0.8101389},"Rotation": {"x": 3.07677078E-06,"y": 0.00469917,"z": -1.1084403E-06}},{"Position": {"x": -0.08544233,"y": 0.100004584,"z": 0.6222505},"Rotation": {"x": -9.46672E-08,"y": 0.005327547,"z": 1.12633177E-06}},{"Position": {"x": -0.08270256,"y": 0.100000657,"z": 0.804303646},"Rotation": {"x": -6.248951E-07,"y": 0.004671849,"z": 2.098166E-