  }]]},{move_to={ -4.057369, 0.099911, -5.193273 }, json=[[{"GUID": "6a1fe4","Name": "Custom_Tile","Transform": {"posX": 87.95764,"posY": 35.71683,"posZ": -56.2873573,"rotX": 0.0180340167,"rotY": 179.964523,"rotZ": 0.07855096,"scaleX": 8.82,"scaleY": 1.0,"scaleZ": 8.82},"Nickname": "Lizard Board","Description": "","GMNotes": "","ColorDiffuse": {"r": 0.905,"g": 0.898,"b": 0.17199412},"LayoutGroupSortIndex": 0,"Value": 0,"Locked": true,"Grid": true,"Snap": true,"IgnoreFoW": false,"MeasureMovement": false,"DragSelectable": true,"Autoraise": true,"Sticky": true,"Tooltip": false,"GridProjection": false,"HideWhenFaceDown": false,"Hands": false,"CustomImage": {"ImageURL": "https://steamusercontent-a.akamaihd.net/ugc/1829027829620962283/612172A62FFB28352E031BCD12EA4042105BD9F9/","ImageSecondaryURL": "https://steamusercontent-a.akamaihd.net/ugc/1829027829620962907/4BBD40ABDEFA4957F312C9F411FC0CDE5A87434B/","ImageScalar": 1.0,"WidthScale": 0.0,"CustomTile": {"Type": 0,"Thickness": 0.1,"Stackable": false,"Stretch": true}},"LuaScript": "----#include root\\lizardboard\nmice = 0\r\nbunnies = 0\r\nfoxes = 0\r\nwait_id = 0\r\n\r\nfunction onLoad(save_state)\r\n    createButtons()\r\n    wait_id = Wait.time(updateButtons, 1, -1)\r\nend\r\n\r\nfunction onDestroy()\r\n    Wait.stop(wait_id)\r\nend\r\n\r\nfunction nothing()\r\nend\r\n\r\nfunction addCard(suit)\r\n    suit = suit:lower()\r\n    if suit == \"fox\" then\r\n        foxes = foxes +1\r\n    elseif suit == \"mouse\" then\r\n        mice = mice + 1\r\n    elseif suit == \"rabbit\" then\r\n        bunnies= bunnies + 1\r\n    end\r\nend\r\n\r\nfunction createButtons()\r\n  self.createButton({\r\n      click_function = \"nothing\",\r\n      function_owner = self,\r\n      label = '0',\r\n      position = {0.74, 0.1, 1.07},\r\n      scale = {0.5, 0.5, 0.5},\r\n      width = 0,\r\n      height = 0,\r\n      font_size = 120,\n      font_color = {r=0.98, g=0.60, b=0.31}\r\n  })\r\n  self.createButton({\r\n      click_function = \"nothing\",\r\n      function_owner = self,\r\n      label = '0',\r\n      position = {0.94, 0.1, 1.07},\r\n      scale = {0.5, 0.5, 0.5},\r\n      width = 0,\r\n      height = 0,\r\n      font_size = 120,\n      font_color = {r=0.98, g=0.93, b=0.36}\r\n  })\r\n  self.createButton({\r\n      click_function = \"nothing\",\r\n      function_owner = self,\r\n      label = '0',\r\n      position = {1.14, 0.1, 1.07},\r\n      scale = {0.5, 0.5, 0.5},\r\n      width = 0,\r\n      height = 0,\r\n      font_size = 120,\n      font_color = {r=0.93, g=0.25, b=0}\r\n  })\r\nend\r\n\r\nfunction updateButtons()\r\n    mice = 0\r\n    foxes = 0\r\n    bunnies = 0\r\n    items = Physics.cast({\r\n        origin       = self.positionToWorld({-0.90, 0.2, 0.55}),\r\n        direction    = self.getTransformUp(),\r\n        type         = 3,\r\n        size         = {3, 0.1, 6},\r\n        max_distance = 2,\r\n    })\r\n    for _, item in ipairs(items) do\r\n        if item.hit_object.tag == \"Card\" then\r\n            addCard(item.hit_object.getDescription())\r\n        end\r\n        if item.hit_object.tag == \"Deck\" then\r\n            for _, card in ipairs(item.hit_object.getObjects()) do\r\n                addCard(card.description)\r\n            end\r\n        end\r\n    end\r\n\r\n    self.editButton({index=0,label=tostring(mice)})\r\n    self.editButton({index=1,label=tostring(bunnies)})\r\n    self.editButton({index=2,label=tostring(foxes)})\r\nend\r\n\n----#include root\\lizardboard","LuaScriptState": "","XmlUI": "","AttachedSnapPoints": [{"Position": {"x": -0.9312044,"y": 0.100161657,"z": 0.5391533},"Rotation": {"x": 1.7666153E-08,"y": 0.0305037927,"z": 180.0}},{"Position": {"x": 0.25824523,"y": 0.09991286,"z": 0.0242952425},"Rotation": {"x": -3.75417449E-06,"y": 0.0100540426,"z": 3.73196542E-07}},{"Position": {"x": 0.08692075,"y": 0.09992861,"z": 0.0235727765},"Rotation": {"x": -3.936133E-06,"y": 0.0350525342,"z": 2.56428649E-07}},{"Position": {"x": -0.0904002,"y": 0.0999578