EVERYTHING['Tools']['Lizard Wizard'] = {color='', data={
  {move_to={ -0.805002, 0.099999, 2.248016 }, json=[[{"GUID": "dc029b","Name": "Custom_Tile","Transform": {"posX": -11.0228529,"posY": 37.3521652,"posZ": -1.75595987,"rotX": 0.0169023052,"rotY": 179.985687,"rotZ": 0.07982485,"scaleX": 3.904294,"scaleY": 1.0,"scaleZ": 3.904294},"Nickname": "Lizard Wizard","Description": "","GMNotes": "","ColorDiffuse": {"r": 1.0,"g": 1.0,"b": 1.0},"LayoutGroupSortIndex": 0,"Locked": true,"Grid": true,"Snap": true,"IgnoreFoW": false,"MeasureMovement": false,"DragSelectable": true, "ColorDiffuse":  {"r": 0.698,"g": 0.812,"b": 0.282}, "Autoraise": true, "Sticky": true,"Tooltip": true,"GridProjection": false,"HideWhenFaceDown": false,"Hands": false,"CustomImage": {"ImageURL": "https://steamusercontent-a.akamaihd.net/ugc/1777200862706584783/428DDFE120C0637EFCBE0D228DB6907428ABDE69/","ImageSecondaryURL": "https://steamusercontent-a.akamaihd.net/ugc/1777201099849412524/CD8605505CE5864B834FFD7E84D6598299D8D6A9/","ImageScalar": 1.0,"WidthScale": 0.0,"CustomTile": {"Type": 3,"Thickness": 0.2,"Stackable": false,"Stretch": true}},"LuaScript": "----#include root\\lizardboard\r\nmice = 0\r\nbunnies = 0\r\nfoxes = 0\r\nwait_id = 0\r\n\r\nfunction onLoad(save_state)\r\n createButtons()\r\n wait_id = Wait.time(updateButtons, 1, -1)\r\nend\r\n\r\nfunction onDestroy()\r\n Wait.stop(wait_id)\r\nend\r\n\r\nfunction nothing()\r\nend\r\n\r\nfunction addCard(suit)\r\n suit = suit:lower()\r\n if string.contains(suit,\"fox\") then\r\n foxes = foxes + 1\r\n end\r\n if string.contains(suit,\"mouse\") then\r\n mice = mice + 1\r\n end\r\n if string.contains(suit,\"rabbit\") then\r\n bunnies= bunnies + 1\r\n end\r\nend\r\n\r\nfunction createButtons()\r\n self.createButton({\r\n click_function = \"nothing\",\r\n function_owner = self,\r\n label = '0',\r\n position = {0.45, 0.25, 0.03},\r\n scale = {0.9, 0.5, 0.9},\r\n width = 0,\r\n height = 0,\r\n font_size = 120\r\n })\r\n self.createButton({\r\n click_function = \"nothing\",\r\n function_owner = self,\r\n label = '0',\r\n position = {0.45, 0.25, 0.4},\r\n scale = {0.9, 0.5, 0.9},\r\n width = 0,\r\n height = 0,\r\n font_size = 120\r\n })\r\n self.createButton({\r\n click_function = \"nothing\",\r\n function_owner = self,\r\n label = '0',\r\n position = {0.45, 0.25, 0.73},\r\n scale = {0.9, 0.5, 0.9},\r\n width = 0,\r\n height = 0,\r\n font_size = 120\r\n })\r\nend\r\n\r\nfunction updateButtons()\r\n mice = 0\r\n foxes = 0\r\n bunnies = 0\r\n items = Physics.cast({\r\n origin = self.positionToWorld({-0.0, 0.2, 0.45}),\r\n direction = self.getTransformUp(),\r\n type = 3,\r\n size = {3, 0.1, 6},\r\n max_distance = 2,\r\n })\r\n for _, item in ipairs(items) do\r\n if item.hit_object.tag == \"Card\" then\r\n addCard(item.hit_object.getDescription())\r\n end\r\n if item.hit_object.tag == \"Deck\" then\r\n for _, card in ipairs(item.hit_object.getObjects()) do\r\n addCard(card.description)\r\n end\r\n end\r\n end\r\n\r\n self.editButton({index=0,label=tostring(mice)})\r\n self.editButton({index=1,label=tostring(bunnies)})\r\n self.editButton({index=2,label=tostring(foxes)})\r\nend\r\n\r\n----#include root\\lizardboard","LuaScriptState": "","XmlUI": "","AttachedSnapPoints": [{"Position": {"x": -0.7220492,"y": 0.200000763,"z": 0.0283633228},"Rotation": {"x": 4.63632581E-08,"y": -0.00319994357,"z": 6.541245E-08},"Tags": []},{"Position": {"x": -0.732150555,"y": 0.200000763,"z": 0.374904454},"Rotation": {"x": 4.63632581E-08,"y": -0.00319994357,"z": 6.541245E-08},"Tags": []},{"Position": {"x": -0.7363231,"y": 0.200000763,"z": 0.7319697},"Rotation": {"x": 4.63632581E-08,"y": -0.00319994357,"z": 6.541245E-08},"Tags": []},{"Position": {"x": 0.483385444,"y": 0.200000763,"z": -0.010193795},"Rotation": {"x": 4.63632581E-08,"y": -0.00319994357,"z": 6.541245E-08},"Tags": []}]
  }]]},{move_to={ 2.053733, 0.299988, 0.784669 }, json=[[{"GUID": "3e8928","Name": "Custom_Tile","Transform": {"posX": -8.163675,"posY": 37.5477371,"posZ": -3.21903872,"rotX": 0.01713503,"rotY": 179.982559,"rotZ": 0.07982133,"scaleX": 0.619459748,"scaleY": 1.0,"scaleZ": 0.619459748},"Nickname": "Outcast Marker","Description": "","GMNotes": "","ColorDiffuse": {"r": 0.905,"g": 0.898,"b": 0.17199266},"LayoutGroupSortIndex": 0,"Locked": false,"Grid": true,"Snap": true,"IgnoreFoW": false,"MeasureMovement": false,"DragSelectable": true,"Autoraise": true,"Sticky": true,"Tooltip": true,"GridProjection": false,"HideWhenFaceDown": false,"Hands": false,"CustomImage": {"ImageURL": "https://steamusercontent-a.akamaihd.net/ugc/4123600330141758623/091E657758D01980A5E81991FD0B7F788EA91867/","ImageSecondaryURL": "https://steamusercontent-a.akamaihd.net/ugc/4123600330141759762/32A6F6DD6A5170FED271D0F2C65B0D198715FA1D/","ImageScalar": 1.0,"WidthScale": 0.0,"CustomTile": {"Type": 3,"Thickness": 0.1,"Stackable": false,"Stretch": true}},"LuaScript": "","LuaScriptState": "","XmlUI": ""
