EVERYTHING['Tools']['Battle Mat'] = {color='', data={
  {move_to={ -1.134426, 0.114935, 2.640131 }, json=[[{"GUID": "2314cc","Name": "Custom_Assetbundle","Transform": {"posX": 35.64778,"posY": 37.312748,"posZ": 34.636116,"rotX": 2.00325179E-08,"rotY": 179.9886,"rotZ": -6.08890645E-08,"scaleX": 1.12499893,"scaleY": 1.12499893,"scaleZ": 1.12499893},"Nickname": "Battle Mat","Description": "","GMNotes": "","ColorDiffuse": {"r": 1.0,"g": 1.0,"b": 1.0},"LayoutGroupSortIndex": 0,"Locked": true,"Grid": true,"Snap": true,"IgnoreFoW": false,"MeasureMovement": false,"DragSelectable": true,"Autoraise": true,"Sticky": true,"Tooltip": true,"GridProjection": false,"HideWhenFaceDown": false,"Hands": false,"CustomAssetbundle": {"AssetbundleURL": "https://steamusercontent-a.akamaihd.net/ugc/1656725692413048205/081DE665C4AA49AF85308E7647C8665BDD530923/","AssetbundleSecondaryURL": "","MaterialIndex": 1,"TypeIndex": 0,"LoopingEffectIndex": 0},"LuaScript": "--Overwrite all dice to be this color (table or false). Overrules diePlayerColor\r\ndieColorOverwrite = false     --ex. {1,0,0} for red\r\n--If a die is colored to match the player who pressed the button for it\r\ndiePlayerColor = true       --true or false\r\n\r\n\r\n--What type of die will be rolled by this tool (only works with 1)\r\ndieType = \"Custom_Dice\"\r\n--Dice type options (quotes required)\r\n--  Die_4\r\n--  Die_6\r\n--  Die_6_Rounded\r\n--  Die_8\r\n--  Die_10\r\n--  Die_12\r\n--  Die_20\r\n--  Custom_Dice --REQUIRES ADDITIONAL ENTRIES BELOW\r\n\r\n--If Custom_Dice is the dice type used, then you must enter info below\r\n--URL for the die image goes in the quotes\r\ndieImage = \"https://steamusercontent-a.akamaihd.net/ugc/1750184828981645969/DC0B90D8A4EC559A72A8A2CD8EC9017863A5CFE8/\"\r\n--Number of sides on die. Options are 4, 6, 8 10, 12, 20\r\ndieSides = 12\r\n\r\n--Time before dice disappear. -1 means they do not (until next roll)\r\nremovalDelay = 10\r\n\r\n--If dice are added together for announcement (true or false)\r\nannounce_total = true\r\n--If individual results are displayed (true or false)\r\nannounce_each = true\r\n--If last player to click button before roll happens gets their name announced\r\nannounce_player = true\r\n\r\n--Distance dice are placed from the tool's center\r\nradialOffset = 3\r\n--Distance die gets moved up\r\nheightOffset = 3\r\n--Die size, default of 1\r\ndieSize = 2\r\n\r\n--How long to wait before rolling the spawned dice\r\nwaitBeforeRoll = 0.5\r\n\r\n--How many dice can be spawned. 0 is infinite\r\ndieLimit = 2\r\n\r\n--Set sound effects default\r\nsoundEffects = false\r\n\r\n--END OF VARIABLES TO EDIT\r\n--Beyond here, there be Lua!\r\n\r\n--Save to track currently active dice for disposal on load\r\nfunction onSave()\r\n    if #currentDice > 0 then\r\n        local currentDiceGUIDs = {}\r\n    for _, obj in ipairs(currentDice) do\r\n        if obj ~= nil then\r\n    table.insert(currentDiceGUIDs, obj.getGUID())\r\n    end\r\n    end\r\n    saved_data = JSON.encode(currentDiceGUIDs)\r\n    else\r\n    saved_data = \"\"\r\n    end\r\n    return saved_data\r\nend\r\n\r\nfunction toggleSound()\r\n    local st = 'OFF'\r\n    if soundEffects then\r\n        soundEffects = false\r\n    else\r\n        soundEffects = true\r\n        st = 'ON'\r\n    end\r\n    print('Battle mat sound turned: ' .. st)\r\nend\r\n\r\nfunction onload(saved_data)\r\n    self.addContextMenuItem(\"Toggle Sound\", toggleSound)\r\n    --Loads the save of any active dice and deletes them\r\n    if saved_data ~= \"\" then\r\n        local loaded_data = JSON.decode(saved_data)\r\n        for _, guid in ipairs(loaded_data) do\r\n            local obj = getObjectFromGUID(guid)\r\n            if obj ~= nil then\r\n            destroyObject(obj)\r\n            end\r\n        end\r\n        currentDice = {}\r\n    else\r\n        currentDice = {}\r\n    end\r\n\r\n    params = {\r\n        click_function = \"click_roll\",\r\n        function_owner = self,\r\n\r\n        position       = {0, 0.01, 0},\r\n        rotation       = {0, 0, 0},\r\n        width          = 4450,\r\n        height         = 4450,\r\n\r\n        color          = {0, 0, 0, 0},\r\n        tooltip        = \"Fight!\",\r\n    }\r\n    self.createButton(params)\r\n\r\n    --Makes the hit vale buttons\r\n    local object, distance = self, 0.85 * self.getScale().x\r\n    local oRot = object.getRotation()\r\n\r\nfor i = 1, 10 do\r\nif i == 1 then\r\nlbl = \"X\"\r\nelse\r\nlbl = i\r\nend\r\nlocal posX = math.sin( math.rad(36*(i-1)+oRot.y) ) * distance\r\nlocal posY = 0.1\r\nlocal posZ = math.cos( math.rad(36*(i-1)+oRot.y) ) * distance\r\nlocal pos = {x=posX, y=posY, z=posZ}\r\nlocal rot = {0,180,0}\r\n--self.createButton({\r\n--click_function=\"click_num\"..i, function_owner=self,\r\n--position=pos, rotation=rot, label = lbl, height=100, width=100, font_size = 100\r\n--})\r\nlocal func = function(_,color) numberButtonPressed(i) end\r\nself.setVar(\"click_num\"..i, func)\r\nend\r\nend\r\n\r\nhitValue = 0\r\n\r\nfunction numberButtonPressed(i)\r\nfor i = 1, 10 do\r\nself.editButton({index=i, color=\"White\"})\r\nend\r\nif i == 1 or i == hitValue then\r\nhitValue = 0\r\nelse\r\nhitValue = i\r\nself.editButton({index=i, color=\"Green\"})\r\nend\r\nend\r\n\r\n--Die spawning and positioning\r\n\r\n--Click function, spawns new dice and waits for a pause to do the rolling\r\nfunction click_roll(_, color)\r\n--Dice spam protection, can be disabled up at top of script\r\nlocal diceCount = 0\r\nfor _ in pairs(currentDice) do\r\ndiceCount = diceCount + 1\r\nend\r\nlocal denyRoll = false\r\nif dieLimit > 0 and diceCount >= dieLimit then\r\ndenyRoll = true\r\nend\r\n--Check for if click is allowed\r\nif rollInProgress == nil and denyRoll == false then\r\n\r\n--Find dice positions, moving previously spawned dice if needed\r\n--local angleStep = 360 / 2\r\n--for i, die in ipairs(currentDice) do\r\n--local pos = findGlobalPosWithLocalDirection(angleStep*(i-1))\r\n--die.setPositionSmooth(pos, false, true)\r\n--end\r\n\r\n--Spawns dice\r\nlocal spawnedDie = spawnObject({\r\ntype=dieType,\r\nposition = findGlobalPosWithLocalDirection(0),\r\nrotation = randomRotation(), scale = getRelativeScale()\r\n})\r\nif dieType == \"Custom_Dice\" then\r\nspawnedDie.setCustomObject({\r\nimage = dieImage,\r\ntype = ref_customDieSides[tostring(dieSides)]\r\n})\r\nrotation_values = {\r\n    {value=0, rotation={x=27, y=0, z=72}},\r\n    {value=1, rotation={x=27, y=0, z=144}},\r\n    {value=2, rotation={x=27, y=0, z=288}},\r\n    {value=0, rotation={x=333, y=180, z=180}},\r\n    {value=3, rotation={x=90, y=180, z=0}},\r\n    {value=2, rotation={x=27, y=0, z=216}},\r\n    {value=2, rotation={x=333, y=180, z=36}},\r\n    {value=0, rotation={x=270, y=180, z=0}},\r\n    {value=3, rotation={x=27, y=0, z=0}},\r\n    {value=3, rotation={x=333, y=180, z=108}},\r\n    {value=1, rotation={x=333, y=108, z=324}},\r\n    {value=1, rotation={x=333, y=36, z=252}},\r\n}\r\nspawnedDie.setRotationValues(rotation_values)\r\nend\r\nspawnedDie.interactable = false\r\nspawnedDie.setLock(true)\r\nif dieColorOverwrite ~= false then\r\nspawnedDie.setColorTint(dieColorOverwrite)\r\nelseif diePlayerColor == true then\r\nspawnedDie.setColorTint(stringColorToRGB(color))\r\nclone_parameters = {position = findGlobalPosWithLocalDirection(0),rotation=randomRotation()}\r\nlocal spawnedDie2 = spawnedDie.clone(clone_parameters);\r\nlocal pos = findGlobalPosWithLocalDirection(-180)\r\nspawnedDie2.setPositionSmooth(pos, false, true)\r\ntable.insert(currentDice, spawnedDie)\r\ntable.insert(currentDice, spawnedDie2)\r\nend\r\n\r\n--Timer starting\r\nTimer.destroy(\"clickRoller_\"..self.getGUID())\r\nTimer.create({\r\nidentifier=\"clickRoller_\"..self.getGUID(), delay=waitBeforeRoll,\r\nfunction_name=\"rollDice\", function_owner=self,\r\nparameters = {color = color}\r\n})\r\nelseif rollInProgress == false then\r\ncleanupDice()\r\nclick_roll(_, color)\r\nelse\r\nPlayer[color].broadcast(\"Roll in progress.\", {0.8, 0.2, 0.2})\r\nend\r\nend\r\n\r\n--Die rolling\r\n\r\n--Rolls all the dice and then launches monitoring\r\nfunction rollDice(p)\r\nrollInProgress = true\r\nif soundEffects then\r\n    self.AssetBundle.playTriggerEffect(1)\r\nend\r\nfunction coroutine_rollDice()\r\nfor _, die in ipairs(currentDice) do\r\ndie.setLock(false)\r\ndie.randomize()\r\nwait(0.1)\r\nend\r\n\r\nmonitorDice(p.color)\r\n\r\nreturn 1\r\nend\r\nstartLuaCoroutine(self, \"coroutine_rollDice\")\r\nend\r\n\r\n--Monitors dice to come to rest\r\nfunction monitorDice(color)\r\nfunction coroutine_monitorDice()\r\nrepeat\r\nlocal allRest = true\r\nfor _, die in ipairs(currentDice) do\r\nif die ~= nil and die.resting == false then\r\nallRest = false\r\nend\r\nend\r\ncoroutine.yield(0)\r\nuntil allRest == true\r\n\r\n--Announcement\r\nif announce_total==true or announce_each==true then\r\nif soundEffects then\r\n    self.AssetBundle.playTriggerEffect(0)\r\nend\r\ndisplayResults(color)\r\nend\r\n\r\nwait(0.1)\r\nrollInProgress = false\r\n\r\nfor _, die in ipairs(currentDice) do\r\ndie.interactable = false\r\nend\r\n\r\n--Auto die removal\r\nif removalDelay ~= -1 then\r\n--Timer starting\r\nTimer.destroy(\"clickRoller_cleanup_\"..self.getGUID())\r\nTimer.create({\r\nidentifier=\"clickRoller_cleanup_\"..self.getGUID(),\r\nfunction_name=\"cleanupDice\", function_owner=self,\r\ndelay=removalDelay,\r\n})\r\nend\r\n\r\nreturn 1\r\nend\r\nstartLuaCoroutine(self, \"coroutine_monitorDice\")\r\nend\r\n\r\n--After roll broadcasting and cleanup\r\nfunction displayResults(color)\r\nlocal total = 0\r\nlocal resultTable = {}\r\nlocal larger = 0\r\nlocal smaller = 0\r\n\r\n\r\n--Tally result info\r\nfor _, die in ipairs(currentDice) do\r\nif die ~= nil then\r\nlocal value = die.getRotationValue()\r\nif value >= hitValue then total = total + 1 end\r\nsmaller = value\r\nif larger > value then\r\nsmaller = value\r\nelseif larger < value then\r\nsmaller = larger\r\nlarger = value\r\nend\r\n--table.insert(resultTable, value)\r\nend\r\nend\r\n\r\ntable.insert(resultTable, larger)\r\ntable.insert(resultTable, smaller)\r\n\r\n--String assembly\r\nlocal s = \"\"\r\nif announce_each == true then\r\nfor i, v in ipairs(resultTable) do\r\nif not (s == \"\"\r\n) then\r\ns = s .. \" and \"\r\nend\r\ns = s .. v\r\nif hitValue > 0 and v >= hitValue then\r\ns = s .. \"#\"\r\nend\r\nend\r\nend\r\nif hitValue > 0 then\r\nif s ~= \"\" then\r\ns = \"Hitting on: \" .. hitValue .. \"  |  \" .. s .. \"  |  \"\r\nend\r\nif total ~= 1 then plural = \"s.\" else plural = \".\" end\r\ns = s .. \"[b]\" .. total .. \" hit\" .. plural .. \"[/b]\"\r\nend\r\nif announce_player == true then\r\ns = Player[color].steam_name .. \"  |  \" .. s\r\nend\r\n\r\nbroadcastToAll(s, stringColorToRGB(color))\r\nend\r\n\r\n--Die cleanup\r\nfunction cleanupDice()\r\nfor _, die in ipairs(currentDice) do\r\nif die ~= nil then\r\ndestroyObject(die)\r\nend\r\nend\r\n\r\nTimer.destroy(\"clickRoller_cleanup_\"..self.getGUID())\r\nrollInProgress = nil\r\ncurrentDice = {}\r\nend\r\n\r\n--Utility functions to obtain info\r\n\r\n--Calculate the scale dice should be, relative to the rolling mat\r\nfunction getRelativeScale()\r\nlocal object = self\r\nlocal matScale = object.getScale()\r\nreturn matScale * dieSize\r\nend\r\n\r\n--Finds a position, rotated around the Y axis, using distance you want + angle\r\n--oPos is object pos, oRot=object rotation, distance = how far, angle = angle in degrees\r\nfunction findGlobalPosWithLocalDirection(angle)\r\nlocal object, distance = self, radialOffset * self.getScale().x\r\nlocal oPos, oRot = object.getPosition(), object.getRotation()\r\nlocal posX = oPos.x + math.sin( math.rad(angle+oRot.y) ) * distance\r\nlocal posY = oPos.y + heightOffset\r\nlocal posZ = oPos.z + math.cos( math.rad(angle+oRot.y) ) * distance\r\nreturn {x=posX, y=posY, z=posZ}\r\nend\r\n\r\n--Gets a random rotation vector\r\nfunction randomRotation()\r\n--Credit for this function goes to Revinor (forums)\r\n--Get 3 random numbers\r\nlocal u1 = math.random();\r\nlocal u2 = math.random();\r\nlocal u3 = math.random();\r\n--Convert them into quats to avoid gimbal lock\r\nlocal u1sqrt = math.sqrt(u1);\r\nlocal u1m1sqrt = math.sqrt(1-u1);\r\nlocal qx = u1m1sqrt *math.sin(2*math.pi*u2);\r\nlocal qy = u1m1sqrt *math.cos(2*math.pi*u2);\r\nlocal qz = u1sqrt *math.sin(2*math.pi*u3);\r\nlocal qw = u1sqrt *math.cos(2*math.pi*u3);\r\n--Apply rotation\r\nlocal ysqr = qy * qy;\r\nlocal t0 = -2.0 * (ysqr + qz * qz) + 1.0;\r\nlocal t1 = 2.0 * (qx * qy - qw * qz);\r\nlocal t2 = -2.0 * (qx * qz + qw * qy);\r\nlocal t3 = 2.0 * (qy * qz - qw * qx);\r\nlocal t4 = -2.0 * (qx * qx + ysqr) + 1.0;\r\n--Correct\r\nif t2 > 1.0 then t2 = 1.0 end\r\nif t2 < -1.0 then ts = -1.0 end\r\n--Convert back to X/Y/Z\r\nlocal xr = math.asin(t2);\r\nlocal yr = math.atan2(t3, t4);\r\nlocal zr = math.atan2(t1, t0);\r\n--Return result\r\nreturn {math.deg(xr),math.deg(yr),math.deg(zr)}\r\nend\r\n\r\n--Coroutine delay, in seconds\r\nfunction wait(time)\r\nlocal start = os.time()\r\nrepeat coroutine.yield(0) until os.time() > start + time\r\nend\r\n\r\n--Data tables\r\nref_customDieSides = {[\"4\"]=0, [\"6\"]=1, [\"8\"]=2, [\"10\"]=3, [\"12\"]=4, [\"20\"]=5}","LuaScriptState": "","XmlUI": ""
  }]]},}}

EVERYTHING['Tools']['Koffin Keeper'] = {color='', data={
  {move_to={ -1.37378, 0.064376, 2.783675 }, json=[[{"GUID": "8a274d","Name": "Custom_Assetbundle","Transform": {"posX": 90.64,"posY": 35.68,"posZ": -48.31,"rotX": 0.0168439839,"rotY": 180.0203,"rotZ": 0.07991002,"scaleX": 6.600006,"scaleY": 6.600006,"scaleZ": 6.600006},"Nickname": "Koffin Keeper","Description": "Holds & counts meeples for Root's 'Coffin Makers' card.\n\nMouseover & press '1' to de-activate!\n\n*MEEPLES MUST HAVE NAMES THAT INCLUDE THE WORD 'WARRIOR' OR THEY WILL NOT BE COUNTED!*\n\nMade by Nevakanezah","GMNotes": "","ColorDiffuse": {"r": 1.0,"g": 1.0,"b": 1.0},"LayoutGroupSortIndex": 0,"Value": 0,"Locked": true,"Grid": true,"Snap": true,"IgnoreFoW": false,"MeasureMovement": false,"DragSelectable": true,"Autoraise": true,"Sticky": true,"Tooltip": true,"GridProjection": false,"HideWhenFaceDown": false,"Hands": false,"CustomAssetbundle": {"AssetbundleURL": "https://steamusercontent-a.akamaihd.net/ugc/1736675300477909275/E4BA5F3F5AB199EFD8977FEFF9EC8126F4238ACC/","AssetbundleSecondaryURL": "","MaterialIndex": 1,"TypeIndex": 1,"LoopingEffectIndex": 0},"LuaScript": "----#include root\\coffinkeeper\r\nwarriors = 0\r\nwait_id = 0\r\n\r\nfunction onLoad(save_state)\r\n    createButtons()\r\n    wait_id = Wait.time(updateButtons, 1, -1)\r\nend\r\n\r\nfunction onDestroy()\r\n    Wait.stop(wait_id)\r\nend\r\n\r\nfunction nothing()\r\nend\r\n\r\nfunction addWarrior(name)\r\n    name = name:lower()\r\n\tif string.match(name, \"warrior\") then\r\n\t\twarriors = warriors + 1\r\n    end\r\nend\r\n\r\nfunction createButtons()\r\n  self.createButton({\r\n      click_function = \"nothing\",\r\n      function_owner = self,\r\n      label = '0',\r\n\t  position = {0.21, 1.7, 0.98}, \r\n\t  rotation = {14, 90, -90}, \r\n\t  scale = {0.5, 0.5, 0.5}, \r\n\t  width = 0,\r\n      height = 0,\r\n\t  font_size = 450\r\n  })\r\nend\r\n\r\nfunction updateButtons()\r\n    warriors = 0\r\n    items = Physics.cast({\r\n        origin       = self.positionToWorld({0, 0, 0.1}),\r\n        direction    = self.getTransformUp(),\r\n\t\torientation  = Vector(self.getRotation()) + Vector({0, 87, 0}), --{0, 87, 0},\r\n        type         = 3,\r\n        size         = {11.5, 7, 7},\r\n        max_distance = 2\r\n    })\r\n    for _, item in ipairs(items) do\r\n        if item.hit_object.tag == \"Figurine\" then\r\n            addWarrior(item.hit_object.getName())\r\n        end\r\n    end\r\n\r\n    self.editButton({index=0,label=tostring(math.floor(warriors/5))})\r\nend\r\n----#include root\\coffinkeeper","LuaScriptState": "","XmlUI": "","States": {"1": {"GUID": "b5014a","Name": "Custom_Assetbundle","Transform": {"posX": 58.9902344,"posY": 35.65214,"posZ": -80.68422,"rotX": 0.01684398,"rotY": 180.0203,"rotZ": 0.07991003,"scaleX": 5.70000267,"scaleY": 5.70000267,"scaleZ": 5.70000267},"Nickname": "Koffin Keeper","Description": "Holds & counts meeples for Root's 'Coffin Makers' card.\n\nMouseover & press '2' to activate!\n\n*MEEPLES MUST HAVE NAMES THAT INCLUDE THE WORD 'WARRIOR' OR THEY WILL NOT BE COUNTED!*\n\nMade by Nevakanezah","GMNotes": "","ColorDiffuse": {"r": 1.0,"g": 1.0,"b": 1.0},"LayoutGroupSortIndex": 0,"Value": 0,"Locked": false,"Grid": true,"Snap": true,"IgnoreFoW": false,"MeasureMovement": false,"DragSelectable": true,"Autoraise": true,"Sticky": true,"Tooltip": true,"GridProjection": false,"HideWhenFaceDown": false,"Hands": false,"CustomAssetbundle": {"AssetbundleURL": "https://steamusercontent-a.akamaihd.net/ugc/1736675300477798481/E3D9619EF83A2523492157D05EE53F7B53FF1946/","AssetbundleSecondaryURL": "","MaterialIndex": 1,"TypeIndex": 1,"LoopingEffectIndex": 0},"LuaScript": "","LuaScriptState": "","XmlUI": ""}}
  }]]},}}

