-a.akamaihd.net/ugc/1859434101954985787/488DB4A1F7E17CACE6CF9B71BEC879C8C604D653/","NumWidth": 2,"NumHeight": 2,"BackIsHidden": false,"UniqueBack": false,"Type": 0}},"LuaScript": "","LuaScriptState": "","XmlUI": ""},{"GUID": "a01c12","Name": "Card","Transform": {"posX": 87.4178,"posY": 40.7662468,"posZ": -58.3181229,"rotX": 359.9824,"rotY": 179.999969,"rotZ": 180.114288,"scaleX": 2.33,"scaleY": 1.0,"scaleZ": 2.33},"Nickname": "","Description": "","GMNotes": "","ColorDiffuse": {"r": 0.713235259,"g": 0.713235259,"b": 0.713235259},"Tags": ["RandomBot"],"LayoutGroupSortIndex": 0,"Value": 0,"Locked": false,"Grid": true,"Snap": true,"IgnoreFoW": false,"MeasureMovement": false,"DragSelectable": true,"Autoraise": true,"Sticky": true,"Tooltip": true,"GridProjection": false,"HideWhenFaceDown": true,"Hands": true,"CardID": 203,"SidewaysCard": false,"CustomDeck": {"2": {"FaceURL": "https://steamusercontent-a.akamaihd.net/ugc/1859434101954984426/BAD5A47510650692847192CEEF84431961D5194B/","BackURL": "https://steamusercontent-a.akamaihd.net/ugc/1859434101954985787/488DB4A1F7E17CACE6CF9B71BEC879C8C604D653/","NumWidth": 2,"NumHeight": 2,"BackIsHidden": false,"UniqueBack": false,"Type": 0}},"LuaScript": "","LuaScriptState": "","XmlUI": ""}]
